    /// Whether this interface is `ancestor` or inherits from it.
    pub fn is_a(self, ancestor: InterfaceId) -> bool {
        let mut cur = Some(self);
        while let Some(i) = cur {
            if i == ancestor {
                return true;
            }
            cur = i.parent();
        }
        false
    }

